screenPanels.initJs:
function(container, apiUrl, tables) {
  // チャート描画関数
  function drawFrequencyChart(canvas, data) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#22c55e';

    const barWidth = width / data.length;
    const maxValue = Math.max(...data.map(d => d.value));

    data.forEach((item, index) => {
      const barHeight = (item.value / maxValue) * (height - 40);
      const x = index * barWidth;
      const y = height - barHeight - 20;

      ctx.fillRect(x + 5, y, barWidth - 10, barHeight);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.fillText(item.label, x + 5, height - 5);
      ctx.fillText(item.value.toString(), x + 5, y - 5);
      ctx.fillStyle = '#22c55e';
    });
  }

  function drawSeasonalChart(canvas, data) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;

    const stepX = width / (data.length - 1);
    const maxValue = Math.max(...data.map(d => d.value));

    ctx.beginPath();
    data.forEach((item, index) => {
      const x = index * stepX;
      const y = height - 20 - ((item.value / maxValue) * (height - 40));

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      ctx.fillStyle = '#22c55e';
      ctx.fillRect(x - 2, y - 2, 4, 4);
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    data.forEach((item, index) => {
      const x = index * stepX;
      ctx.fillText(item.label, x - 10, height - 5);
    });
  }

  function drawIntervalChart(canvas, data) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#22c55e';

    const barWidth = width / data.length;
    const maxValue = Math.max(...data.map(d => d.count));

    data.forEach((item, index) => {
      const barHeight = (item.count / maxValue) * (height - 40);
      const x = index * barWidth;
      const y = height - barHeight - 20;

      ctx.fillRect(x + 2, y, barWidth - 4, barHeight);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '9px sans-serif';
      ctx.fillText(item.interval + '日', x + 2, height - 5);
      ctx.fillStyle = '#22c55e';
    });
  }

  function drawCompositionChart(canvas, data) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const centerX = width / 2;
    const centerY = height / 2;
    const radius = Math.min(width, height) / 2 - 20;

    ctx.clearRect(0, 0, width, height);

    const colors = ['#22c55e', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6'];
    let currentAngle = 0;
    const total = data.reduce((sum, item) => sum + item.value, 0);

    data.forEach((item, index) => {
      const sliceAngle = (item.value / total) * 2 * Math.PI;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fillStyle = colors[index % colors.length];
      ctx.fill();

      // ラベル
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.7);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.7);

      ctx.fillStyle = '#ffffff';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(item.label, labelX, labelY);

      currentAngle += sliceAngle;
    });
  }

  function drawPriceSensitivityChart(canvas, data) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    const margin = 40;
    const chartWidth = width - margin * 2;
    const chartHeight = height - margin * 2;

    const maxPrice = Math.max(...data.map(d => d.price));
    const maxQuantity = Math.max(...data.map(d => d.quantity));

    // 軸
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin, margin);
    ctx.lineTo(margin, height - margin);
    ctx.lineTo(width - margin, height - margin);
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#22c55e';
    data.forEach(item => {
      const x = margin + (item.price / maxPrice) * chartWidth;
      const y = height - margin - (item.quantity / maxQuantity) * chartHeight;

      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('価格', width - 30, height - 10);
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('数量', 0, 0);
    ctx.restore();
  }

  // テーブル再描画関数
  function renderCustomerRanking(data) {
    const tbody = container.querySelector('#customer-ranking-tbody');
    tbody.innerHTML = data.map((item, index) => `
      <tr>
        <td>${index + 1}</td>
        <td>${item.customerName || ''}</td>
        <td>¥${(item.amount || 0).toLocaleString()}</td>
        <td style="color: ${item.growth >= 0 ? '#22c55e' : '#ef4444'}">${item.growth >= 0 ? '+' : ''}${item.growth || 0}%</td>
      </tr>
    `).join('');
  }

  function renderRepeatRate(data) {
    const tbody = container.querySelector('#repeat-rate-tbody');
    tbody.innerHTML = data.map(item => `
      <tr>
        <td>${item.category || ''}</td>
        <td>${item.repeatRate || 0}%</td>
        <td>${item.avgInterval || 0}日</td>
        <td>
          <span style="background: ${item.confidence >= 80 ? '#22c55e' : item.confidence >= 60 ? '#f59e0b' : '#ef4444'}; color: white; padding: 2px 6px; border-radius: 3px; font-size: 11px;">
            ${item.confidence || 0}%
          </span>
        </td>
      </tr>
    `).join('');
  }

  function renderPatternClassification(rows) {
    const tbody = container.querySelector('#pattern-classification-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.分析結果ID || r.id}">
        <td>${r.分析結果ID || r.id || ''}</td>
        <td>${r.分析対象期間開始日 ? new Date(r.分析対象期間開始日).toLocaleDateString() : ''} - ${r.分析対象期間終了日 ? new Date(r.分析対象期間終了日).toLocaleDateString() : ''}</td>
        <td>${r.商品カテゴリ || ''}</td>
        <td>${r.平均発注間隔日数 || 0}日</td>
        <td>${(r.平均発注数量 || 0).toLocaleString()}</td>
        <td>${r.季節変動係数 || ''}</td>
        <td>${r.価格感度指数 || 0}</td>
        <td>${r.推奨発注タイミング || ''}</td>
        <td>
          <span style="background: ${(r.信頼度スコア || 0) >= 80 ? '#22c55e' : (r.信頼度スコア || 0) >= 60 ? '#f59e0b' : '#ef4444'}; color: white; padding: 2px 6px; border-radius: 3px; font-size: 11px;">
            ${r.信頼度スコア || 0}%
          </span>
        </td>
        <td>
          <span style="background: ${r.ステータス === '有効' ? '#22c55e' : r.ステータス === '検証中' ? '#f59e0b' : '#6b7280'}; color: white; padding: 2px 6px; border-radius: 3px; font-size: 11px;">
            ${r.ステータス || ''}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ描画
  const purchasePatternData = tables[2]?.records || [];
  renderPatternClassification(purchasePatternData);

  // サンプルデータでチャート描画
  const frequencyData = [
    {label: '週1回', value: 25},
    {label: '月2回', value: 35},
    {label: '月1回', value: 40},
    {label: '不定期', value: 15}
  ];

  const seasonalData = [
    {label: '春', value: 120},
    {label: '夏', value: 95},
    {label: '秋', value: 140},
    {label: '冬', value: 85}
  ];

  const intervalData = [
    {interval: '7', count: 15},
    {interval: '14', count: 25},
    {interval: '30', count: 35},
    {interval: '60', count: 20},
    {interval: '90+', count: 5}
  ];

  const compositionData = [
    {label: '電子部品', value: 35},
    {label: '機械部品', value: 28},
    {label: '工具', value: 20},
    {label: '材料', value: 17}
  ];

  const priceSensitivityData = [
    {price: 100, quantity: 50},
    {price: 120, quantity: 45},
    {price: 150, quantity: 35},
    {price: 180, quantity: 25},
    {price: 200, quantity: 20}
  ];

  const customerRankingData = [
    {customerName: 'ABC商事', amount: 5500000, growth: 12},
    {customerName: 'XYZ工業', amount: 4200000, growth: -5},
    {customerName: 'DEF製作所', amount: 3800000, growth: 8},
    {customerName: 'GHI株式会社', amount: 2900000, growth: 15}
  ];

  const repeatRateData = [
    {category: '電子部品', repeatRate: 85, avgInterval: 21, confidence: 92},
    {category: '機械部品', repeatRate: 72, avgInterval: 35, confidence: 78},
    {category: '工具', repeatRate: 65, avgInterval: 45, confidence: 65},
    {category: '材料', repeatRate: 90, avgInterval: 14, confidence: 95}
  ];

  // チャート描画
  setTimeout(() => {
    drawFrequencyChart(container.querySelector('#frequency-chart'), frequencyData);
    drawSeasonalChart(container.querySelector('#seasonal-chart'), seasonalData);
    drawIntervalChart(container.querySelector('#interval-chart'), intervalData);
    drawCompositionChart(container.querySelector('#composition-chart'), compositionData);
    drawPriceSensitivityChart(container.querySelector('#price-sensitivity-chart'), priceSensitivityData);
  }, 100);

  renderCustomerRanking(customerRankingData);
  renderRepeatRate(repeatRateData);

  // 分析実行ボタン
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const customerSegment = container.querySelector('#customer-segment').value;
    const productCategory = container.querySelector('#product-category').value;

    // 分析実行（実際のAPIコール）
    const rows = await window.aivicApi.list(2);
    if (rows) {
      let filteredRows = rows;

      if (startDate) {
        filteredRows = filteredRows.filter(r => new Date(r.分析対象期間開始日) >= new Date(startDate));
      }
      if (endDate) {
        filteredRows = filteredRows.filter(r => new Date(r.分析対象期間終了日) <= new Date(endDate));
      }
      if (productCategory) {
        filteredRows = filteredRows.filter(r => r.商品カテゴリ === productCategory);
      }

      renderPatternClassification(filteredRows);

      // 異常値検知アラート表示
      const lowConfidenceItems = filteredRows.filter(r => (r.信頼度スコア || 0) < 60);
      if (lowConfidenceItems.length > 0) {
        const alertPanel = container.querySelector('#alert-panel');
        const alertContent = container.querySelector('#alert-content');
        alertContent.textContent = `信頼度が低い分析結果が${lowConfidenceItems.length}件検出されました。データの見直しを推奨します。`;
        alertPanel.classList.remove('hidden');
      }
    }
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(2);
    if (!rows) return;

    const headers = ['分析結果ID', '分析対象期間開始日', '分析対象期間終了日', '商品カテゴリ', '平均発注間隔日数', '平均発注数量', '季節変動係数', '価格感度指数', '推奨発注タイミング', '信頼度スコア', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.分析結果ID || '',
        r.分析対象期間開始日 || '',
        r.分析対象期間終了日 || '',
        r.商品カテゴリ || '',
        r.平均発注間隔日数 || '',
        r.平均発注数量 || '',
        r.季節変動係数 || '',
        r.価格感度指数 || '',
        r.推奨発注タイミング || '',
        r.信頼度スコア || '',
        r.ステータス || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '購買パターン分析結果.csv';
    link.click();
  });

  // 自動分析開始
  setTimeout(() => {
    container.querySelector('#btn-analyze').click();
  }, 500);
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderCustomerPriceRows(rows) {
    const tbody = container.querySelector("#customer-price-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.分析結果ID}">
        <td>${r.顧客名|| ""}</td>
        <td>${r.商品カテゴリ || ""}</td>
        <td style="text-align: right;">¥${(r.顧客単価 || 0).toLocaleString()}</td>
        <td style="text-align: right;">¥${(r.市場平均単価 || 0).toLocaleString()}</td>
        <td style="text-align: right; color: ${(r.単価差額 || 0) > 0 ? '#22c55e' : '#ef4444'};">¥${(r.単価差額 || 0).toLocaleString()}</td>
        <td style="text-align: right; color: ${(r.単価差率 || 0) > 0 ? '#22c55e' : '#ef4444'};">${r.単価差率 || 0}%</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; background: ${
            r.価格競争力ランク === '高' ? 'rgba(34, 197, 94, 0.2)' : 
            r.価格競争力ランク === '中' ? 'rgba(245, 158, 11, 0.2)' : 'rgba(239, 68, 68, 0.2)'
          }; color: ${
            r.価格競争力ランク === '高' ? '#22c55e' : 
            r.価格競争力ランク === '中' ? '#f59e0b' : '#ef4444'
          };">${r.価格競争力ランク || "中"}</span>
        </td>
        <td style="text-align: right;">¥${(r.推奨価格 || 0).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.分析結果ID}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.分析結果ID}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  function renderPriceSensitivityRows(rows) {
    const tbody = container.querySelector("#price-sensitivity-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.分析結果ID}">
        <td>${r.商品カテゴリ || ""}</td>
        <td>${r.顧客セグメント || ""}</td>
        <td>${r.価格弾力性 || ""}</td>
        <td style="text-align: right;">${r.価格感度指数 || 0}</td>
        <td>${r.推奨戦略 || ""}</td>
        <td style="text-align: right;">${r.信頼度 || ""}%</td>
        <td>${r.適用開始予定日 ? new Date(r.適用開始予定日).toLocaleDateString() : ""}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; background: ${
            r.承認状況 === '承認済' ? 'rgba(34, 197, 94, 0.2)' : 'rgba(245, 158, 11, 0.2)'
          }; color: ${
            r.承認状況 === '承認済' ? '#22c55e' : '#f59e0b'
          };">${r.承認状況 || "未承認"}</span>
        </td>
      </tr>
    `).join("");
  }

  // チャート描画関数
  function drawPriceTrendChart() {
    const canvas = container.querySelector("#price-trend-chart");
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = '#1a2a4a';
    ctx.fillRect(0, 0, width, height);

    // グリッド
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 1; i < 5; i++) {
      const y = (height / 5) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    // 価格推移線
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();
    const points = [
      {x: 50, y: 150}, {x: 100, y: 140}, {x: 150, y: 130}, 
      {x: 200, y: 125}, {x: 250, y: 135}, {x: 300, y: 120}, {x: 350, y: 115}
    ];
    points.forEach((point, i) => {
      if (i === 0) ctx.moveTo(point.x, point.y);
      else ctx.lineTo(point.x, point.y);
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('市場価格推移', 10, 20);
  }

  function drawCompetitorChart() {
    const canvas = container.querySelector("#competitor-chart");
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = '#1a2a4a';
    ctx.fillRect(0, 0, width, height);

    // 競合価格バー
    const competitors = [
      {name: '自社', price: 120, color: '#22c55e'},
      {name: '競合A', price: 110, color: '#3b82f6'},
      {name: '競合B', price: 125, color: '#f59e0b'},
      {name: '競合C', price: 115, color: '#ef4444'}
    ];

    competitors.forEach((comp, i) => {
      const barHeight = (comp.price / 130) * (height - 40);
      const x = 50 + i * 80;
      const y = height - barHeight - 20;

      ctx.fillStyle = comp.color;
      ctx.fillRect(x, y, 60, barHeight);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.fillText(comp.name, x + 5, height - 5);
      ctx.fillText(`¥${comp.price}`, x + 5, y - 5);
    });

    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('競合価格比較', 10, 20);
  }

  // 2. 初期データ読み込みと描画
  window.aivicApi.list(4).then(rows => {
    if (rows) renderCustomerPriceRows(rows);
  });

  window.aivicApi.list(3).then(rows => {
    if (rows) renderPriceSensitivityRows(rows);
  });

  // チャート描画
  setTimeout(() => {
    drawPriceTrendChart();
    drawCompetitorChart();
  }, 100);

  // 3. 分析実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const category = container.querySelector("#select-category").value;

    const segments = [];
    if (container.querySelector("#check-enterprise").checked) segments.push("大企業");
    if (container.querySelector("#check-sme").checked) segments.push("中小企業");
    if (container.querySelector("#check-startup").checked) segments.push("スタートアップ");
    if (container.querySelector("#check-government").checked) segments.push("官公庁");

    // 分析結果を保存
    const analysisResult = await window.aivicApi.save(3, {
      分析対象期間開始日: startDate || new Date().toISOString(),
      分析対象期間終了日: endDate || new Date().toISOString(),
      商品カテゴリ: category || "全カテゴリ",
      顧客セグメント: segments.join(",") || "全セグメント",
      現在価格: 12000,
      推奨価格: 11400,
      市場平均価格: 11800,
      競合最低価格: 10500,
      価格弾力性: "中程度",
      売上予測増減率: 5,
      利益率予測: 28,
      分析手法: "回帰分析",
      信頼度: "高",
      承認状況: "未承認",
      作成者ID: "user-001"
    });

    if (analysisResult) {
      // 再描画
      window.aivicApi.list(3).then(rows => {
        if (rows) renderPriceSensitivityRows(rows);
      });
      window.aivicApi.list(4).then(rows => {
        if (rows) renderCustomerPriceRows(rows);
      });

      // チャート更新
      drawPriceTrendChart();
      drawCompetitorChart();
    }
  });

  // 4. 利益率シミュレーター
  const adjustmentSlider = container.querySelector("#input-price-adjustment");
  const adjustmentValue = container.querySelector("#adjustment-value");
  const revenueChange = container.querySelector("#revenue-change");
  const profitMargin = container.querySelector("#profit-margin");

  adjustmentSlider.addEventListener("input", (e) => {
    const value = parseInt(e.target.value);
    adjustmentValue.textContent = `${value}%`;

    // シミュレーション計算
    const revenueChangeValue = Math.round(value * -0.8); // 価格弾力性を考慮
    const profitMarginValue = Math.max(0, 25 + value * 1.2);

    revenueChange.textContent = `${revenueChangeValue > 0 ? '+' : ''}${revenueChangeValue}%`;
    revenueChange.style.color = revenueChangeValue >= 0 ? '#22c55e' : '#ef4444';

    profitMargin.textContent = `${profitMarginValue.toFixed(1)}%`;
  });

  // 5. エクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const customerRows = await window.aivicApi.list(4);
    const sensitivityRows = await window.aivicApi.list(3);

    if (!customerRows || !sensitivityRows) return;

    let csvContent = "\uFEFF"; // BOM
    csvContent += "価格戦略分析結果\n\n";
    csvContent += "顧客別単価分析\n";
    csvContent += "顧客名,商品カテゴリ,顧客単価,市場平均単価,単価差額,単価差率,価格競争力ランク,推奨価格\n";

    customerRows.forEach(row => {
