function(container, apiUrl, tables) {
  let currentData = [];
  let chartInstance = null;

  // チャート描画関数
  function drawChart(data) {
    const canvas = container.querySelector('#price-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 60 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // データの最大値を取得
    const maxPrice = Math.max(...data.map(d => Math.max(d.顧客単価 || 0, d.市場平均単価 || 0)));
    const priceScale = chartHeight / maxPrice;

    // 背景
    ctx.fillStyle = '#f8f9fa';
    ctx.fillRect(margin.left, margin.top, chartWidth, chartHeight);

    // グリッド線
    ctx.strokeStyle = '#e9ecef';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = margin.top + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(margin.left, y);
      ctx.lineTo(margin.left + chartWidth, y);
      ctx.stroke();
    }

    // バー描画
    const barWidth = chartWidth / data.length / 2 - 2;
    data.forEach((item, index) => {
      const x = margin.left + (index * chartWidth / data.length);

      // 顧客単価バー
      const customerHeight = (item.顧客単価 || 0) * priceScale;
      ctx.fillStyle = '#28a745';
      ctx.fillRect(x, margin.top + chartHeight - customerHeight, barWidth, customerHeight);

      // 市場平均単価バー
      const marketHeight = (item.市場平均単価 || 0) * priceScale;
      ctx.fillStyle = '#6c757d';
      ctx.fillRect(x + barWidth + 2, margin.top + chartHeight - marketHeight, barWidth, marketHeight);
    });

    // 軸ラベル
    ctx.fillStyle = '#495057';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    data.forEach((item, index) => {
      const x = margin.left + (index * chartWidth / data.length) + barWidth;
      const customerName = (item.顧客名|| '').substring(0, 8);
      ctx.fillText(customerName, x, canvas.height - 10);
    });

    // 凡例
    ctx.fillStyle = '#28a745';
    ctx.fillRect(margin.left, 5, 15, 10);
    ctx.fillStyle = '#495057';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('顧客単価', margin.left + 20, 14);

    ctx.fillStyle = '#6c757d';
    ctx.fillRect(margin.left + 100, 5, 15, 10);
    ctx.fillText('市場平均', margin.left + 120, 14);
  }

  // KPI更新関数
  function updateKPIs(data) {
    const customerCount = new Set(data.map(d => d.顧客ID)).size;
    const avgDiff = data.length > 0 ? 
      (data.reduce((sum, d) => sum + (d.単価差率 || 0), 0) / data.length).toFixed(1) : 0;
    const recommendations = data.filter(d => d.価格改定推奨フラグ).length;
    const totalImpact = data.reduce((sum, d) => sum + ((d.推奨価格 || 0) - (d.顧客単価 || 0)) * (d.取引数量 || 0), 0);

    container.querySelector('#kpi-customers').textContent = customerCount;
    container.querySelector('#kpi-avg-diff').textContent = avgDiff + '%';
    container.querySelector('#kpi-recommendations').textContent = recommendations;
    container.querySelector('#kpi-impact').textContent = '¥' + totalImpact.toLocaleString();
  }

  // テーブル再描画関数
  function renderResults(data) {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = data.map(row => `
      <tr data-id="${row.分析結果ID || ''}">
        <td>${row.顧客名 || ''}</td>
        <td>${row.商品名 || ''}</td>
        <td>¥${(row.顧客単価 || 0).toLocaleString()}</td>
        <td>¥${(row.市場平均単価 || 0).toLocaleString()}</td>
        <td style="color: ${(row.単価差額 || 0) >= 0 ? '#28a745' : '#dc3545'};">¥${(row.単価差額 || 0).toLocaleString()}</td>
        <td style="color: ${(row.単価差率 || 0) >= 0 ? '#28a745' : '#dc3545'};">${(row.単価差率 || 0).toFixed(1)}%</td>
        <td>
          <span class="px-2 py-1 text-xs rounded" style="background: ${getRankColor(row.価格競争力ランク)}; color: #fff;">
            ${row.価格競争力ランク || ''}
          </span>
        </td>
        <td>¥${(row.推奨価格 || 0).toLocaleString()}</td>
        <td>
          ${row.価格改定推奨フラグ ? '<span class="px-2 py-1 text-xs rounded" style="background: #ff6a00; color: #fff;">推奨</span>' : ''}
        </td>
        <td>
          <button class="action-btn secondary strategy-btn" data-id="${row.分析結果ID || ''}" style="font-size: 11px; padding: 2px 6px;">戦略提案</button>
        </td>
      </tr>
    `).join('');

    updateKPIs(data);
    drawChart(data.slice(0, 10)); // 上位10件をチャート表示
  }

  function getRankColor(rank) {
    switch(rank) {
      case '高': return '#28a745';
      case '中': return '#ffc107';
      case '低': return '#dc3545';
      default: return '#6c757d';
    }
  }

  // 初期データ表示
  currentData = tables[4]?.records || [];
  renderResults(currentData);

  // 分析実行
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const customerFilter = container.querySelector('#customer-filter').value;
    const categoryFilter = container.querySelector('#category-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    try {
      const data = await window.aivicApi.list(4);
      if (data) {
        let filtered = data;

        if (customerFilter) {
          filtered = filtered.filter(d => d.顧客ID === customerFilter);
        }
        if (categoryFilter) {
          filtered = filtered.filter(d => d.商品カテゴリ === categoryFilter);
        }
        if (startDate) {
          filtered = filtered.filter(d => new Date(d.分析対象期間開始日) >= new Date(startDate));
        }
        if (endDate) {
          filtered = filtered.filter(d => new Date(d.分析対象期間終了日) <= new Date(endDate));
        }

        currentData = filtered;
        renderResults(currentData);
      }
    } catch (error) {
      console.error('分析実行エラー:', error);
    }
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#search-input').value.toLowerCase();
    const filtered = currentData.filter(row => 
      JSON.stringify(row).toLowerCase().includes(keyword)
    );
    renderResults(filtered);
  });

  // 条件リセット
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#customer-filter').value = '';
    container.querySelector('#category-filter').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#search-input').value = '';
    renderResults(tables[4]?.records || []);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
