      if (data) {
        const headers = ['顧客名', '商品名', '顧客単価', '市場平均単価', '差額', '差率', '競争力ランク', '推奨価格', '改定推奨'];
        const csvContent = '\uFEFF' + [
          headers.join(','),
          ...data.map(row => [
            row.顧客名 || '',
            row.商品名 || '',
            row.顧客単価 || 0,
            row.市場平均単価 || 0,
            row.単価差額 || 0,
            (row.単価差率 || 0) + '%',
            row.価格競争力ランク || '',
            row.推奨価格 || 0,
            row.価格改定推奨フラグ ? '推奨' : ''
          ].join(','))
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = '顧客別単価比較分析_' + new Date().toISOString().split('T')[0] + '.csv';
        link.click();
      }
    } catch (error) {
      console.error('エクスポートエラー:', error);
    }
  });

  // レポート生成
  container.querySelector('#btn-generate-report').addEventListener('click', async () => {
    const reportData = {
      レポート名: '顧客別単価比較分析レポート_' + new Date().toISOString().split('T')[0],
      レポート種別: '顧客別単価比較',
      対象期間開始日: new Date().toISOString(),
      対象期間終了日: new Date().toISOString(),
      レポート内容: `分析対象顧客数: ${container.querySelector('#kpi-customers').textContent}\n平均単価差率: ${container.querySelector('#kpi-avg-diff').textContent}\n価格改定推奨件数: ${container.querySelector('#kpi-recommendations').textContent}`,
      ステータス: '完了',
      公開フラグ: true,
      通知済フラグ: false,
